import java.util.*;

class Solution {
  private final List<Long> sums = new ArrayList<>();

  public boolean checkEqualTree(TreeNode root) {
    long total = sum(root);
    sums.remove(sums.size() - 1); // the whole tree is not a valid half
    if (total % 2 != 0) return false;
    return sums.contains(total / 2);
  }

  private long sum(TreeNode node) {
    if (node == null) return 0;
    long s = node.val + sum(node.left) + sum(node.right);
    sums.add(s);
    return s;
  }
}
